<template><main class="auth-page"><section class="auth-shell"><p class="auth-kicker">Account recovery</p><h1>Choose a new password</h1><p class="auth-intro">Reset links expire after 30 minutes and can only be used once.</p><p v-if="message" class="auth-message" :class="{error}">{{message}}</p><form v-if="!complete" class="auth-form" @submit.prevent="submit"><div class="auth-field"><label for="password">New password</label><input id="password" v-model="password" type="password" autocomplete="new-password" minlength="6" required></div><div class="auth-field"><label for="confirm">Confirm password</label><input id="confirm" v-model="confirm" type="password" autocomplete="new-password" minlength="6" required></div><button class="auth-submit" :disabled="loading">{{loading?'Updating...':'Update password'}}</button></form><div v-if="complete" class="auth-links"><NuxtLink to="/login">Log in with your new password</NuxtLink></div></section></main></template>
<script setup lang="ts">const route=useRoute();const password=ref('');const confirm=ref('');const loading=ref(false);const complete=ref(false);const error=ref(false);const message=ref('');const auth=useMemberAuth();const submit=async()=>{if(password.value!==confirm.value){error.value=true;message.value='Passwords do not match.';return}const token=typeof route.query.token==='string'?route.query.token:'';if(!token){error.value=true;message.value='The reset token is missing.';return}loading.value=true;error.value=false;try{await auth.resetPassword(token,password.value);complete.value=true;message.value='Your password has been updated. Existing sessions have been signed out.'}catch(e){error.value=true;message.value=e instanceof Error?e.message:'This link is invalid or expired.'}finally{loading.value=false}};</script>
